// D39 · Part 2 · 가짜 라벨과 확신 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d39_pseudo.ts   (소리·데이터는 코드 안에서 합성해요)
//   받아쓴 글에 토큰 확률로 확신을 붙이고 문턱으로 믿을 만한 것만 남기기


const SR = 16000; // 말소리 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

