    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}


function burst(nSyl: number, f0: number, amp: number): Float32Array {
  // 말소리 비슷한 합성 소리: 음절 nSyl개(음절 하나 0.18초, 앞 85%는 소리)
  const L = Math.floor(0.18 * SR);
  const m = Math.floor(L * 0.85);
  const y = new Float32Array(nSyl * L);
  for (let i = 0; i < nSyl; i++) {
    for (let j = 0; j < m; j++) y[i * L + j] = amp * Math.sin((2 * Math.PI * (f0 + 10 * Math.sin(i)) * j) / SR) * (0.5 - 0.5 * Math.cos((2 * Math.PI * j) / (m - 1)));
  }
  return y;
}

function session(seed: number = 0, noiseDb: number = -55, nUtt: number = 5, amp: number = 0.3): { y: Float32Array; truth: Array<[number, number]> } {
  // [대체] 실제 녹음 대신 합성 세션: 말 nUtt개를 0.6~1.2초 쉼 사이에 두고 배경 잡음(noiseDb dB)을 깐다. → (소리, 실제 말 구간)
  const rnd = mulberry32(seed);
  const parts: Float32Array[] = [new Float32Array(Math.floor(0.5 * SR))];
  const truth: Array<[number, number]> = [];
  let t = 0.5;
  for (let k = 0; k < nUtt; k++) {
    const u = burst(8 + Math.floor(rnd() * 7), 120 + 60 * rnd(), amp);
    const gap = 0.6 + 0.6 * rnd();
    truth.push([t, t + u.length / SR]);
    parts.push(u, new Float32Array(Math.floor(gap * SR)));
    t += u.length / SR + gap;
  }
  const y = new Float32Array(parts.reduce((s, p) => s + p.length, 0));
  let off = 0;
  for (const p of parts) {
    y.set(p, off);
    off += p.length;
  }
  const g = 10 ** (noiseDb / 20);
  for (let i = 0; i < y.length; i++) y[i] += g * gauss(rnd);
  return { y, truth };
}


function augSpeed(y: Float32Array, rate: number = 1.1): Float32Array {
  // rate배 빠르게: 표본화율을 속여 다시 표본화 (길이 ÷ rate, 높낮이 x rate)
  const n = Math.ceil((y.length - 1) / rate);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const x = i * rate;
    const k = Math.floor(x);
    out[i] = y[k] + (y[Math.min(k + 1, y.length - 1)] - y[k]) * (x - k);
  }
  return out;
}

function power(a: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * a[i];
  return s / a.length;
}

function mixAtSnr(speech: Float32Array, noise: Float32Array, snr: number): Float32Array {
  // 말과 잡음을 정한 SNR(dB)이 되게 섞기: 잡음에 곱할 값 g = 루트(말 전력 / (잡음 전력 x 10^(snr/10)))
  const nz = Float32Array.from({ length: speech.length }, (_, i) => noise[i % noise.length]);
  const g = Math.sqrt(power(speech) / (power(nz) * 10 ** (snr / 10)));
  return speech.map((v, i) => v + g * nz[i]);
}

function augRir(y: Float32Array, rt60: number = 0.3, seed: number = 0): Float32Array {
  // 울림: 지수로 줄어드는 잡음을 방의 임펄스 응답으로 삼아 합성곱
  const r = mulberry32(seed);
  const n = Math.floor(rt60 * SR);
  const h = new Float64Array(n);
  for (let i = 0; i < n; i++) h[i] = gauss(r) * Math.exp((-6.9 * i) / SR / rt60);
  h[0] = 1;
  const norm = Math.sqrt(h.reduce((a, b) => a + b * b, 0));
  const out = new Float32Array(y.length + n - 1);
  for (let i = 0; i < y.length; i++) for (let j = 0; j < n; j++) out[i + j] += (y[i] * h[j]) / norm;
  return out;
}

function augCodec(y: Float32Array, mu: number = 255): { out: Float32Array; q: Uint8Array } {
  // 전화 코덱: 8 kHz로 줄이고 μ-law 8비트로 양자화한 뒤 다시 16 kHz로 복원. → (복원한 소리, 8비트 값)
  const m = Math.floor(y.length / 2);
  const q = new Uint8Array(m);
  const out = new Float32Array(2 * m);
  for (let i = 0; i < m; i++) {
    const x = (y[2 * i] + y[2 * i + 1]) / 2; // 두 개씩 평균 = 간단한 저역 통과 + 8 kHz
    const c = (Math.sign(x) * Math.log1p(mu * Math.abs(x))) / Math.log1p(mu);
    q[i] = Math.round(((c + 1) / 2) * 255); // 8비트: 값 256가지
    const c2 = (q[i] / 255) * 2 - 1;
    const x2 = (Math.sign(c2) * ((1 + mu) ** Math.abs(c2) - 1)) / mu;
    out[2 * i] = x2;
    out[2 * i + 1] = x2;
  }
  return { out, q };
}

function zcr(y: Float32Array): number {
  let z = 0;
  for (let i = 1; i < y.length; i++) if (y[i] < 0 !== y[i - 1] < 0) z++;
  return z / (y.length - 1);
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율 = 편집 거리 / 참조 글자 수
  const a = [...ref];
  const b = [...hyp];
  let d = Array.from({ length: b.length + 1 }, (_, j) => j);
  a.forEach((ca, i) => {
    const nd = [i + 1];
    b.forEach((cb, j) => nd.push(Math.min(d[j + 1] + 1, nd[j] + 1, d[j] + (ca === cb ? 0 : 1))));
    d = nd;
  });
  return d[b.length] / a.length;
}

const y = burst(10, 140, 0.3);
const rr = mulberry32(0);
const noise = Float32Array.from({ length: y.length }, () => gauss(rr));
const fast = augSpeed(y);
const noisy = mixAtSnr(y, noise, 10.0);
const room = augRir(y);
const { out: coded, q } = augCodec(y);
const meas = 10 * Math.log10(power(y) / power(noisy.map((v, i) => v - y[i])));
const yc = y.subarray(0, coded.length);
const snrCodec = 10 * Math.log10(power(yc) / power(coded.map((v, i) => v - yc[i])));
console.log(`속도 1.1배: 길이 ${y.length} → ${fast.length} · 영점 통과율 x${(zcr(fast) / zcr(y)).toFixed(2)}(높낮이도 약 1.1배)`);
console.log(`잡음 SNR 10 dB: 실제로 잰 SNR ${meas.toFixed(2)} dB · 울림: 길이 ${y.length} → ${room.length} · 코덱: 값 ${new Set(q).size}가지 · 원본과의 SNR ${snrCodec.toFixed(1)} dB`);
// 합성(TTS) 데이터 역검증: 합성한 소리를 다시 받아써서 CER이 높으면 버린다. [대체] 받아쓴 글은 직접 적어 둔 값
const SYN: Array<[string, string]> = [
  ["임플란트 시술은 두 번에 나눠 진행합니다", "임플란트 시술은 두 번에 나눠 진행합니다"],
  ["신경 치료 후에는 크라운을 씌워야 합니다", "신경 치료 후에는 크라운을 씨워야 합니다"],
  ["스케일링은 일 년에 한 번 건강보험이 적용됩니다", "스케일 링은 일 년 한번 건강 보험 적용"],
];
const keep = SYN.map(([r, h]) => cer(r, h) <= 0.1);
console.log("합성 문장 CER:", SYN.map(([r, h]) => cer(r, h).toFixed(2)).join(", "), "→ 남김", keep.join(", "));
check(
  Math.abs(fast.length - y.length / 1.1) < 2 &&
    zcr(fast) / zcr(y) > 1.05 &&
    zcr(fast) / zcr(y) < 1.15 &&
    Math.abs(meas - 10.0) < 0.05 &&
    room.length === y.length + Math.floor(0.3 * SR) - 1 &&
    new Set(q).size <= 256 &&
    snrCodec > 10 &&
    snrCodec < 45 &&
    cer("가나다", "가나다") === 0 &&
    Math.abs(cer("가나다라", "가나다") - 0.25) < 1e-12 &&
    keep.join() === "true,true,false",
  "정한 SNR로 섞이고, 빠르게 하면 높낮이도 올라가고, 합성 문장은 CER 0.1 이하만 남아야 해요.",
);

deid.typescript:
// D39 · Part 4 · 비식별화: 글자와 소리 가리기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d39_deid.ts   (소리·데이터는 코드 안에서 합성해요)
//   글자에서 이름 · 전화번호를 찾아 가리고 정렬 시각으로 소리에 비프음 넣기


const SR = 16000; // 말소리 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}


const PII: Array<[string, RegExp]> = [
  ["이름", /(?<=이름은 )[가-힣]{2,4}(?=입니다)/g],
  ["전화", /01\d-\d{3,4}-\d{4}/g],
]; // 찾는 규칙(실무에서는 개체명 인식 모델도 함께)
const TEXT = "제 이름은 김민준입니다 전화번호는 010-1234-5678입니다";
const SEC_PER_CHAR = 0.15;
const PAD = 0.05; // [대체] 정렬 결과 대신 글자 하나 0.15초로 가정한 시각표

function findPii(text: string): Array<[number, number, string]> {
  // → [(시작 글자 위치, 끝 글자 위치, 종류), ...]
  const out: Array<[number, number, string]> = [];
  for (const [kind, re] of PII) for (const m of text.matchAll(re)) out.push([m.index as number, (m.index as number) + m[0].length, kind]);
  return out.sort((a, b) => a[0] - b[0]);
}

function maskText(text: string): string {
  let t = text;
  for (const [s, e, kind] of findPii(text).reverse()) t = `${t.slice(0, s)}[${kind}]${t.slice(e)}`;
  return t;
}

function speakChars(text: string): Float32Array {
  // [대체] TTS 대신: 공백이 아닌 글자마다 0.15초 소리, 공백은 쉼
  const n = Math.floor(SEC_PER_CHAR * SR);
  const chars = [...text];
  const y = new Float32Array(chars.length * n);
  chars.forEach((c, k) => {
    if (c === " ") return;
    for (let i = 0; i < n; i++) y[k * n + i] = 0.3 * Math.sin((2 * Math.PI * (180 + 7 * ((c.codePointAt(0) as number) % 20)) * i) / SR) * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
  });
  return y;
}

function beep(y: Float32Array, start: number, end: number, freq: number = 1000.0, amp: number = 0.1): Float32Array {
  // 소리의 start ~ end(초) 구간을 비프음으로 바꾼 복사본
  const out = y.slice();
  const a = Math.floor(start * SR);
  const b = Math.floor(end * SR);
  for (let i = a; i < b; i++) out[i] = amp * Math.sin((2 * Math.PI * freq * (i - a)) / SR);
  return out;
}

function maskAudio(y: Float32Array, text: string): { masked: Float32Array; spans: Array<[number, number]> } {
  // 글자 위치 → 시각(글자 수 x 0.15초)으로 바꿔 해당 구간에 비프음
  const spans = findPii(text).map(([s, e]): [number, number] => [Math.max(0, s * SEC_PER_CHAR - PAD), e * SEC_PER_CHAR + PAD]);
  let masked = y;
  for (const [a, b] of spans) masked = beep(masked, a, b);
  return { masked, spans };
}

const nz = (a: Float32Array, s: number, e: number): number => a.slice(Math.floor(s * SR), Math.floor(e * SR)).filter((v) => v !== 0).length;
const t0 = beep(new Float32Array(SR), 0.25, 0.5);
check(t0.length === SR && nz(t0, 0, 0.25) === 0 && nz(t0, 0.5, 1) === 0 && nz(t0, 0.25, 0.5) > 3000, "비프음은 정한 구간만 바꾸고 앞뒤는 그대로여야 해요.");
const y = speakChars(TEXT);
const { masked, spans } = maskAudio(y, TEXT);
console.log("원문 :", TEXT);
console.log("가림 :", maskText(TEXT));
console.log("가린 구간(초):", spans.map(([a, b]) => `(${a.toFixed(2)}, ${b.toFixed(2)})`).join(", "));
const inside = (i: number): boolean => spans.some(([s, e]) => i >= Math.floor(s * SR) && i < Math.floor(e * SR));
let same = true;
for (let i = 0; i < y.length; i++) if (!inside(i) && masked[i] !== y[i]) same = false;
const a0 = Math.floor(spans[0][0] * SR);
const b0 = Math.floor(spans[0][1] * SR);
const rmsIn = Math.sqrt(masked.subarray(a0, b0).reduce((s, v) => s + v * v, 0) / (b0 - a0));
check(
  findPii(TEXT).length === 2 && !maskText(TEXT).includes("김민준") && !maskText(TEXT).includes("010") && same && Math.abs(rmsIn - 0.1 / Math.sqrt(2)) < 0.005,
  "이름과 전화번호 두 곳을 찾아 글자와 소리를 모두 가리고, 나머지 소리는 그대로여야 해요.",
);

split.typescript:
// D39 · Part 4-2 · 화자 단위로 나누고 저장하기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d39_split.ts   (소리·데이터는 코드 안에서 합성해요)
//   같은 사람이 학습 · 평가에 함께 들어가지 않게 나누고 JSONL · 데이터 카드로 저장


import { mkdirSync, readFileSync, writeFileSync } from "node:fs";


const SR = 16000; // 말소리 표본화율 (16 kHz)
const HOP = 320; // 20 ms마다 한 번 잼

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}

function frameDb(y: Float32Array): number[] {
  // 20 ms마다 (조각 길이 40 ms) 소리 크기 dB
  const n = Math.floor((y.length - 640) / HOP) + 1;
  const out: number[] = [];
  for (let f = 0; f < n; f++) {
    let s = 0;
    for (let i = 0; i < 640; i++) s += y[f * HOP + i] ** 2;
    out.push(20 * Math.log10(Math.sqrt(s / 640) + 1e-9));
  }
  return out;
}

function percentile(a: number[], p: number): number {
  // 백분위수(선형 보간)
  const s = [...a].sort((x, y) => x - y);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
}


interface Utt {
  id: string;
  speaker: string;
  text: string;
  sec: number;
}

const SPEAKERS = Array.from({ length: 10 }, (_, i) => ({ id: `S${String(i + 1).padStart(2, "0")}`, train: i + 1 !== 4, publish: false })); // S04는 학습 동의가 없다
const UTT: Utt[] = SPEAKERS.flatMap((s) => Array.from({ length: 8 }, (_, k): Utt => ({ id: `${s.id}_${String(k).padStart(3, "0")}`, speaker: s.id, text: `문장 ${k}`, sec: 2.0 + 0.1 * k })));
const rnd = mulberry32(0);

function shuffle<T>(a: T[]): T[] {
  const x = [...a];
  for (let i = x.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [x[i], x[j]] = [x[j], x[i]];
  }
  return x;
}

function splitSpeakers(speakers: string[]): Record<string, string> {
  // 화자 목록 → {화자: 'train' | 'valid' | 'test'}: 화자를 섞은 뒤 통째로 배정한다(약 70 / 15 / 15)
  const ids = shuffle(speakers);
  const nTest = Math.max(1, Math.round(ids.length * 0.15));
  const nValid = nTest;
  return Object.fromEntries(ids.map((s, i) => [s, i < nTest ? "test" : i < nTest + nValid ? "valid" : "train"]));
}

const allowed = SPEAKERS.filter((s) => s.train).map((s) => s.id); // 동의한 화자만
const WHERE = splitSpeakers(allowed);
const rows = UTT.filter((u) => u.speaker in WHERE);
mkdirSync("hanbit_speech_mini", { recursive: true });
const count: Record<string, number> = {};
for (const sp of ["train", "valid", "test"]) {
  const part = rows.filter((u) => WHERE[u.speaker] === sp);
  writeFileSync(`hanbit_speech_mini/${sp}.jsonl`, `${part.map((u) => JSON.stringify(u)).join("\n")}\n`, "utf-8");
  count[sp] = part.length;
}
const card = `# hanbit_speech_mini 데이터 카드\n- 화자 ${allowed.length}명 (동의하지 않은 화자 ${SPEAKERS.length - allowed.length}명 제외) · 발화 ${rows.length}개\n- 나누기: 화자 단위 train ${count.train} / valid ${count.valid} / test ${count.test} 발화\n- 공개: 하지 않음 · 합성 데이터 · 연습용\n`;
writeFileSync("hanbit_speech_mini/CARD.md", card, "utf-8");
console.log(card);
const back: Record<string, Utt[]> = {};
for (const sp of Object.keys(count)) back[sp] = readFileSync(`hanbit_speech_mini/${sp}.jsonl`, "utf-8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l) as Utt);
const who: Record<string, Set<string>> = Object.fromEntries(Object.entries(back).map(([sp, us]) => [sp, new Set(us.map((u) => u.speaker))]));
const both = (a: Set<string>, b: Set<string>): number => [...a].filter((x) => b.has(x)).length;
const shuffled = shuffle(rows.map((u) => u.speaker)); // 잘못된 방법: 발화를 섞어서 나누면 같은 사람이 양쪽에 들어간다
const cut = Math.floor(rows.length * 0.85);
const leak = both(new Set(shuffled.slice(0, cut)), new Set(shuffled.slice(cut)));
console.log(`화자 단위: 겹치는 화자 ${both(who.train, who.test)}명 · 발화 단위로 섞으면 학습과 평가에 함께 들어간 화자 ${leak}명`);
check(
  !("S04" in WHERE) &&
    both(who.train, who.valid) + both(who.train, who.test) + both(who.valid, who.test) === 0 &&
    count.train + count.valid + count.test === allowed.length * 8 &&
    count.test === 8 &&
    count.valid === 8 &&
    leak >= 1 &&
    Object.values(back).reduce((a, v) => a + v.length, 0) === rows.length &&
    card.includes("동의하지 않은 화자 1명"),
  "동의 없는 화자는 빼고, 같은 화자는 한 곳에만 넣고, 저장한 파일을 다시 읽어도 개수가 같아야 해요.",
);

