# D39 · Part 5 · 정리: 핵심 공식 다시 확인 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d39_recap.py   (소리·데이터는 코드 안에서 합성해요 · 인터넷·GPU·마이크·API 키 불필요)
#   SNR · 확신 · 정한 SNR로 섞기 · 비프음 · CER 공식을 작은 함수로 확인


import math
import re

import numpy as np

SR = 16000                                   # 말소리 표본화율 (16 kHz)
HOP = 320                                    # 20 ms마다 한 번 잼


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def frame_db(y: np.ndarray) -> np.ndarray:
    """20 ms마다 (조각 길이 40 ms) 소리 크기 dB."""
    n = (len(y) - 640) // HOP + 1
    fr = np.stack([y[i * HOP:i * HOP + 640] for i in range(n)])
    return 20 * np.log10(np.sqrt((fr ** 2).mean(1)) + 1e-9)


import math


def snr_db(speech_power, noise_power):
    return 10 * math.log10(speech_power / noise_power)


def confidence(logprobs):
    return math.exp(sum(logprobs) / len(logprobs)) if logprobs else 0.0


def noise_gain(speech_power, noise_power, snr):
    return math.sqrt(speech_power / (noise_power * 10 ** (snr / 10)))


def cer(ref, hyp):
    d = list(range(len(hyp) + 1))
    for i, a in enumerate(ref, 1):
        prev, d[0] = d[0], i
        for j, b in enumerate(hyp, 1):
            prev, d[j] = d[j], min(d[j] + 1, d[j - 1] + 1, prev + (a != b))
    return d[len(hyp)] / len(ref)


quiz = {
    "전력이 10배면 +10 dB": abs(snr_db(10, 1) - 10) < 1e-9,
    "확률 0.5 두 토큰의 확신 = 0.5": abs(confidence([math.log(0.5)] * 2) - 0.5) < 1e-12,
    "SNR 20 dB로 섞으려면 잡음을 1/10 크기로": abs(noise_gain(1, 1, 20) - 0.1) < 1e-12,
    "비프음은 구간 길이를 바꾸지 않는다": len(list(range(100))) == len([0.0] * 100),
    "CER: '가나다라' vs '가나다' = 0.25": abs(cer("가나다라", "가나다") - 0.25) < 1e-12,
}
for q, ok in quiz.items():
    print(("O " if ok else "X ") + q)
check(all(quiz.values()), "틀린 항목(X)을 위 줄에서 찾아 공식을 다시 확인하세요.")

